/*
 * A037994  Numbers whose maximal base 8 run length is 3.
 * https://oeis.org/A037994
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   Numbers whose maximal base 8 run length is 3 The sequence is
 *            generated by testing integers in order and keeping those whose
 *            base‑8 representation contains a longest run of equal digits of
 *            length exactly 3
 * Range:     u8 n <= 3, u16 n <= 41, u32 n <= 41, u64 n <= 41, u128 n <= 41,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>

static bool has_max_run3(seq_t v)
{
    /* Return true iff the base‑8 representation of v has a
       longest run of equal digits of length exactly 3. */
    seq_t zero = (seq_t)0;
    if (v == zero) return false;        /* 0 never occurs in the sequence */

    int prev = -1;       /* previous digit, -1 means none */
    int run = 0;         /* current run length */
    int maxrun = 0;      /* longest run seen */

    while (v > zero) {
        int d = (int)(v % (seq_t)8);   /* digit in base 8 */
        if (d == prev) {
            run++;
        } else {
            prev = d;
            run = 1;
        }
        if (run > maxrun) maxrun = run;
        if (maxrun > 3) return false;  /* early exit if too long */
        v = v / (seq_t)8;
    }
    return maxrun == 3;
}

static seq_t *cache = NULL;
static size_t cache_size = 0;   /* number of terms stored in cache */
static size_t cache_cap  = 0;   /* current allocation size */
static idx_t next_to_test = 1;  /* first candidate that has not yet been checked */

static void extend_cache(size_t target)
{
    if (cache_size >= target) return;
    if (cache == NULL) {
        cache_cap = 64;
        cache = (seq_t*)malloc(sizeof(seq_t) * cache_cap);
    }
    /* Search for additional terms until we have 'target' of them */
    while (cache_size < target) {
        seq_t val = (seq_t)next_to_test;
        if (has_max_run3(val)) {
            if (cache_size >= cache_cap) {
                cache_cap <<= 1;
                cache = (seq_t*)realloc(cache, sizeof(seq_t) * cache_cap);
            }
            cache[cache_size++] = val;
        }
        next_to_test++;
    }
}

seq_t a(idx_t n)
{
    /* Return the n-th term of the sequence.  The function is
       idempotent and works for calls in any order. */
    if (n == 0) return (seq_t)0;   /* undefined for n==0, but harmless */
    extend_cache((size_t)n);
    return cache[(size_t)n-1];
}
